import{_ as a,o,c as r,a3 as e}from"./chunks/framework.DsQ8uxR7.js";const m=JSON.parse('{"title":"关于Konado","description":"","frontmatter":{"title":"关于Konado","order":1},"headers":[],"relativePath":"zh/introduction/konado.md","filePath":"zh/introduction/konado.md","lastUpdated":1778242448000}'),i={name:"zh/introduction/konado.md"};function s(d,t,h,n,c,p){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="关于konado" tabindex="-1">关于Konado <a class="header-anchor" href="#关于konado" aria-label="Permalink to &quot;关于Konado&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>Konado是一款基于Godot Engine的视觉小说引擎框架，由开源社区驱动。Konado致力于为开发者提供高效、便捷的视觉小说开发体验，助力创作者快速构建高质量的视觉小说作品，为创作赋能。</p><h2 id="我们的目标" tabindex="-1">我们的目标 <a class="header-anchor" href="#我们的目标" aria-label="Permalink to &quot;我们的目标&quot;">​</a></h2><p>我们致力于自主开发一套完整的视觉小说游戏框架，不依赖任何第三方现有解决方案。Konado的目标是打造更友好、更高效的工具，让游戏创作者能够专注于故事叙述和艺术表现，而非陷入程序实现的细节中。</p><h2 id="赞助我们" tabindex="-1">赞助我们 <a class="header-anchor" href="#赞助我们" aria-label="Permalink to &quot;赞助我们&quot;">​</a></h2><p>如果您喜欢Konado项目，并希望支持我们的工作，可以通过以下方式赞助我们：</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">爱发电</a></li></ul><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如果您对Konado项目感兴趣，欢迎加入我们的QQ频道交流群组，与我们共同探讨Konado项目的未来发展方向：</p><p>QQ频道交流群组：<a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></p><p>如有问题反馈或功能建议，欢迎前往Konado的项目<a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">仓库提交 Issue</a></p><p>如果是其他问题，欢迎发送邮件至：konadoproject@163.com</p><a href="https://godothub.com"><img src="https://godothub.com/licon/godothub.png" alt="godothub" style="width:65%;"></a><h2 id="项目荣誉" tabindex="-1">项目荣誉 <a class="header-anchor" href="#项目荣誉" aria-label="Permalink to &quot;项目荣誉&quot;">​</a></h2><p>我们很荣幸能获得<a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit百大开源项目</a>荣誉，并被收录在<a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a>生态全景图中。</p><h2 id="项目贡献者" tabindex="-1">项目贡献者 <a class="header-anchor" href="#项目贡献者" aria-label="Permalink to &quot;项目贡献者&quot;">​</a></h2><p>以下图表通过<a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a>生成，实时更新项目贡献者信息。</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="Contributors" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">Github Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;Github Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History Chart" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p>',23)])])}const u=a(i,[["render",s]]);export{m as __pageData,u as default};
